  ["waiting"] = "en attente",
  ["CPU: captured frame cadence. GPU: graphics-queue frame interval. Peaks: last 2 seconds."] = "CPU : cadence des images capturées. GPU : intervalle d'images de la file graphique. Pics : 2 dernières secondes.",
  ["Output FPS excludes repeated frames; it is not a headset scanout measurement."] = "Les FPS de sortie excluent les images répétées ; ce n'est pas une mesure du balayage du casque.",
  ["Lows use the mean of the slowest 1%% / 0.1%% of real-frame intervals. Hardware polling: 1 Hz."] = "Les bas utilisent la moyenne des 1%% / 0.1%% intervalles d'images réelles les plus lents. Relevé matériel : 1 Hz.",
  ["FPS overlay and statistics are off."] = "L'overlay FPS et les statistiques sont désactivés.",
  ["Recenter HMD (F7)"] = "Recentrer le HMD (F7)",
  ["GENERAL"] = "GÉNÉRAL",
  ["CAS Sharpening"] = "Netteté CAS",
  ["Contrast-adaptive sharpening for both eyes. 0 = off, 1 = full strength. Disabled automatically with game DLAA."] = "Netteté adaptative au contraste pour les deux yeux. 0 = désactivé, 1 = pleine force. Désactivée automatiquement avec le DLAA du jeu.",
  ["FIXED FOVEATED RENDERING"] = "RENDU FOVÉAL FIXE",
  ["Peripheral quality"] = "Qualité périphérique",
  ["Off"] = "Désactivé",
  ["Quality"] = "Qualité",
  ["Balanced"] = "Équilibré",
  ["Performance"] = "Performances",
  ["The center follows game DLSS/DLAA. Peripheral DLAA uses 100%% / 75%% / 50%% of the game's render resolution."] = "Le centre suit le DLSS/DLAA du jeu. Le DLAA périphérique utilise 100%% / 75%% / 50%% de la résolution de rendu du jeu.",
  ["Center width"] = "Largeur du centre",
  ["Full-quality region width as a percentage of each eye image."] = "Largeur de la zone pleine qualité en pourcentage de l'image de chaque œil.",
  ["Center height"] = "Hauteur du centre",
  ["Full-quality region height as a percentage of each eye image."] = "Hauteur de la zone pleine qualité en pourcentage de l'image de chaque œil.",
  ["Center offset X"] = "Décalage du centre X",
  ["Percentage of eye-image width. Negative = left, positive = right."] = "Pourcentage de la largeur de l'image de l'œil. Négatif = gauche, positif = droite.",
  ["Center offset Y"] = "Décalage du centre Y",
  ["Percentage of eye-image height. Negative = up, positive = down toward the hands."] = "Pourcentage de la hauteur de l'image de l'œil. Négatif = haut, positif = bas vers les mains.",
  ["Show region boundary"] = "Afficher la limite de la zone",
  ["DLSS GPU: native %.2f ms / foveated %.2f ms"] = "DLSS GPU : natif %.2f ms / fovéal %.2f ms",
  ["Shared sun shadows"] = "Ombres solaires partagées",
  ["Render sun cascades once for both eyes. Shadow quality and distance remain controlled by the game."] = "Rend les cascades solaires une seule fois pour les deux yeux. La qualité et la distance des ombres restent gérées par le jeu.",
  ["Scope lens stabilization"] = "Stabilisation de la lentille de lunette",
  ["Magnifying scope lenses while the view moves: share of the stabilised image (percent). Higher: no blinking of lights and grates, softer. 0 = off. Standing still the lens is untouched."] = "Lentilles grossissantes des lunettes quand la vue bouge : part de l'image stabilisée (pourcentage). Plus haut : pas de clignotement des lumières et des grilles, plus doux. 0 = désactivé. À l'arrêt, la lentille n'est pas modifiée.",
  ["VARIABLE RATE SHADING"] = "VARIABLE RATE SHADING",
  ["Peripheral shading"] = "Ombrage périphérique",
  [" 2 x 2"] = " 2 x 2",
  [" 4 x 4"] = " 4 x 4",
  ["Opaque scene materials in both eyes. The center stays 1 x 1. Unsupported 4 x 4 falls back to 2 x 2."] = "Matériaux opaques de la scène dans les deux yeux. Le centre reste en 1 x 1. Sans prise en charge, 4 x 4 revient à 2 x 2.",
  ["Unavailable: GPU resource error"] = "Indisponible : erreur de ressource GPU",
  ["VRS Tier 2 unavailable"] = "VRS Tier 2 indisponible",
  ["Preparing"] = "Préparation",
  ["%s | %u px tiles"] = "%s | tuiles de %u px",
  ["4 x 4"] = "4 x 4",
  ["2 x 2"] = "2 x 2",
  ["HIDDEN AREA MASK"] = "MASQUE DES ZONES CACHÉES",
  ["Mask lens edges"] = "Masquer les bords des lentilles",
  ["Skips shading the parts of each eye image the lens never shows. The visible area is unchanged."] = "Ignore l'ombrage des parties de l'image de chaque œil que la lentille ne montre jamais. La zone visible ne change pas.",
  ["Visible radius"] = "Rayon visible",
  ["Size of the shaded area as a percentage of the eye's field of view: 100%% touches its edges, 141%% masks nothing inside it.\nLower it until a dark border appears at the edge of the lens, then raise it until the border is gone."] = "Taille de la zone ombrée en pourcentage du champ de vision de l'œil : 100%% touche ses bords, 141%% ne masque rien à l'intérieur.\nBaissez jusqu'à voir une bordure sombre au bord de la lentille, puis remontez jusqu'à ce qu'elle disparaisse.",
  ["Waiting for the scene depth"] = "En attente de la profondeur de scène",
  ["Masked %.1f %% / %.1f %% of pixels (MAIN / VRCAM)"] = "Masqués %.1f %% / %.1f %% des pixels (MAIN / VRCAM)",
  ["GAME MENUS"] = "MENUS DU JEU",
  ["VR menu quad"] = "Plan du menu VR",
  ["VR menu FOV"] = "FOV du menu VR",
  ["Tracking / Camera"] = "Suivi / caméra",
  ["Locomotion direction is set in the Controls tab."] = "La direction de déplacement se règle dans l'onglet Commandes.",
  ["Disable Mouse Y (Pitch)"] = "Désactiver la souris Y (tangage)",
  ["Suppress mouse/right-stick pitch so only the HMD controls\nvertical look. Applied by the CET VRIK mod and the\nXInput merge. On by default."] = "Supprime le tangage de la souris/du stick droit pour que seul le HMD contrôle\nle regard vertical. Appliqué par le mod CET VRIK et la\nfusion XInput. Activé par défaut.",
  ["Head X right"] = "Tête X droite",
  ["Head Y forward"] = "Tête Y avant",
  ["Head Z up"] = "Tête Z haut",
  ["Debug Gizmos"] = "Gizmos de débogage",
  ["Raw hand overlay / debug gizmos:"] = "Overlay brut des mains / gizmos de débogage :",
  ["Enable hand overlay"] = "Activer l'overlay des mains",
  ["Draw 3D hand proxy"] = "Dessiner la main 3D",
  ["Draw debug wire/axes"] = "Dessiner les fils/axes de débogage",
  ["Locator scale"] = "Échelle des repères",
  ["Verbose log (spammy diag)"] = "Journal détaillé (diag verbeux)",
  ["Off by default for a clean cyberpunkvrport.log. Enable only\nwhen capturing ClipCursor / depth / hook diagnostics."] = "Désactivé par défaut pour un cyberpunkvrport.log propre. À activer uniquement\npour capturer des diagnostics ClipCursor / profondeur / hooks.",
  ["FRAMEGEN"] = "GÉN. D'IMAGES",
  ["Enable frame generation"] = "Activer la génération d'images",
  ["While frame generation is enabled, hand smoothing runs at its rate times xr_hand_lerp_framegen_scale (1.5; 0 turns it off)."] = "Avec la génération d'images, le lissage des mains tourne à sa fréquence multipliée par xr_hand_lerp_framegen_scale (1.5 ; 0 le désactive).",
  ["Frame generator"] = "Générateur d'images",
  ["FidelityFX"] = "FidelityFX",
  ["NVIDIA OFA + FidelityFX"] = "NVIDIA OFA + FidelityFX",
  ["NVIDIA DLSS Frame Generation"] = "NVIDIA DLSS Frame Generation",
  ["DLSS Frame Generation is not available here (%s); FidelityFX is used."] = "DLSS Frame Generation n'est pas disponible ici (%s) ; FidelityFX est utilisé.",
  ["NVIDIA optical flow is not available on this GPU; FidelityFX optical flow is used."] = "Le flux optique NVIDIA n'est pas disponible sur ce GPU ; le flux optique FidelityFX est utilisé.",
  ["NVIDIA quality"] = "Qualité NVIDIA",
  ["Fast (performance)"] = "Rapide (performances)",
  ["Medium (balanced)"] = "Moyen (équilibré)",
  ["Slow (best)"] = "Lent (meilleur)",
  ["Optical flow"] = "Flux optique",
  ["Off (game vectors only)"] = "Désactivé (vecteurs du jeu uniquement)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "Les vecteurs de mouvement du jeu décrivent déjà presque tout ; le flux optique ajoute du temps GPU\net de la mémoire pour ce qu'ils manquent (certaines particules et effets).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "Le modèle de génération d'images de NVIDIA sur les vecteurs de mouvement et la profondeur du jeu. Qualité maximale, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Cadence adaptative des images réelles",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Jusqu'à la moitié du rafraîchissement du casque. Laisse plus de temps GPU aux images générées quand des images réelles voisines sont manquées.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "Utilise les vecteurs de mouvement et la profondeur du jeu dans les deux yeux. Ajoute une image intermédiaire entre les images réelles.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "Activer le panneau HUD",
  ["Head / free-look cone"] = "Tête / cône de vue libre",
  ["Follow"] = "Suivi",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Rattrape au-delà du cône, ou après 3 secondes d'immobilité si le décalage en lacet dépasse 10° à l'intérieur.",
  ["HUD FOV"] = "FOV du HUD",
  ["Stereo depth"] = "Profondeur stéréo",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Désactivé : le HUD a la même direction dans les deux yeux.\nActivé : le place à la profondeur physique choisie.",
  ["Depth"] = "Profondeur",
  ["Brightness"] = "Luminosité",
  ["Shadow / outline"] = "Ombre / contour",
  ["Glow"] = "Lueur",
  ["INTERACTIONS / DIALOGS"] = "INTERACTIONS / DIALOGUES",
  ["World-space interactions / dialogs"] = "Interactions / dialogues dans le monde",
  ["Interaction free-look cone"] = "Cône de vue libre des interactions",
  ["Loot free-look cone"] = "Cône de vue libre du butin",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Utilisé tant que le panneau de butin et la description de l'objet sont visibles. Par défaut : 10°.",
  ["Interaction distance"] = "Distance des interactions",
  ["Interaction FOV"] = "FOV des interactions",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Les invites d'interaction et les choix de dialogue partagent ce panneau. Il ne suit qu'au-delà du cône ; pas de rattrapage différé à l'arrêt.",
  ["Element"] = "Élément",
  ["Not currently visible in gameplay; settings are still saved."] = "Pas visible en jeu actuellement ; les réglages sont tout de même enregistrés.",
  ["Show element"] = "Afficher l'élément",
  ["Horizontal offset"] = "Décalage horizontal",
  ["Vertical offset"] = "Décalage vertical",
  ["Size"] = "Taille",
  ["Opacity"] = "Opacité",
  ["Reset element"] = "Réinitialiser l'élément",
  ["Reset all elements"] = "Réinitialiser tous les éléments",
  ["CONTROLS"] = "COMMANDES",
  ["DRIVING"] = "CONDUITE",
  ["BINDINGS"] = "ASSIGNATIONS",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Raccourcis de déplacement, de visée et d'interaction physique.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Visée à la main  (désactivé = visée tête VR découplée)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "ACTIVÉ (visée à la main) : la manette oriente l'arme et VRIK pilote les bras.\nDÉSACTIVÉ (visée tête VR découplée) : l'ARME suit votre tête, le jeu\ngarde sa position et ses animations ADS, et VRIK lâche\nle bras de l'arme. Dans les deux cas, le tir part de la vraie bouche du canon, pour les balles\ncomme pour les projectiles, et la vue libre en visant est conservée.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Point laser de visée (là où la balle touche)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Point rouge projeté depuis la direction réelle de la bouche du canon à travers la\ncaméra du jeu -- marque exactement où la balle ira.",
  ["Controller vibration"] = "Vibration des manettes",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Retour haptique : chaque tir selon la classe d'arme (pistolet, fusil, fusil à pompe, sniper),\nblocage et parade au corps à corps, blocage et déviation de balles, atteinte d'un élément de ceinture,\ndégoupillage d'une grenade. Prise à deux mains : les deux ; à une main : une.",
  ["Vibration strength"] = "Intensité des vibrations",
  ["Enable VR -> XInput merge"] = "Activer la fusion VR -> XInput",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Combine (OR) l'état des manettes VR avec la manette XInput 0 à chaque lecture.\nDésactivé = le jeu ne voit qu'une manette physique / rien.",
  ["Weapon holsters (reach + right grip)"] = "Holsters d'armes (atteindre + gâchette latérale droite)",
  ["Immersive holsters"] = "Holsters immersifs",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "ON  - l'arme est choisie par le holster VISIBLE que vous atteignez :\n      au-dessus de l'épaule droite = arme principale (fusil / sniper),\n      hanche avec katana = mêlée, hanche avec pistolet = arme de poing.\nOFF - holsters visibles ignorés, emplacement fixe par zone :\n      au-dessus de l'épaule = EquipmentSlot1, hanche droite = Slot2, hanche gauche = Slot3.\nAtteignez la zone et serrez la gâchette latérale DROITE pour équiper / ranger.",
  ["Locomotion direction"] = "Direction de déplacement",
  ["Analog movement"] = "Déplacement analogique",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Activé : la vitesse suit la course du stick gauche. Désactivé : le déplacement actuel à vitesse fixe (par défaut).\nLes commandes des véhicules gardent leur réponse actuelle.",
  ["Left stick deadzone"] = "Zone morte du stick gauche",
  ["Right stick deadzone"] = "Zone morte du stick droit",
  ["Full input threshold"] = "Seuil d'entrée complète",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Course brute qui donne une entrée analogique complète et déclenche sprint, esquive et accroupissement.\nLa course utile entre la zone morte et ce seuil correspond à 0-100%%.",
  ["Game (camera)"] = "Jeu (caméra)",
  ["HMD (head)"] = "HMD (tête)",
  ["Left hand"] = "Main gauche",
  ["Right hand"] = "Main droite",
  ["Move source"] = "Source de déplacement",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Jeu      - le stick gauche avance dans la direction de la caméra (d'origine).\nHMD      - le stick gauche avance dans la direction du casque.\nMain gauche/droite - avance là où pointe la manette choisie.\nLes véhicules gardent toujours la direction du jeu.",
  ["Breaststroke swimming"] = "Nage brasse",
  ["Physical crouch"] = "Accroupissement physique",
  ["Physical crouch depth"] = "Profondeur d'accroupissement physique",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Perte de hauteur après l'inclinaison mesurée. Se relever met fin à l'accroupissement physique.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "Dans l'eau : tendez les deux mains vers l'avant, écartez-les et tirez vers l'arrière.\nLe mouvement commence pendant la traction. Des mouvements doux nagent normalement ; des tractions rapides accélèrent.\nNagez là où pointe le casque, y compris vers le haut/bas ; pas besoin de stick.\nPour remonter, levez les mains écartées à hauteur de poitrine et poussez-les vers le bas.\nRépétez les mouvements pour avancer. Tirez le stick gauche vers l'arrière pour vous arrêter.",
  ["Ladder grip climbing"] = "Escalade d'échelle à la main",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Saisissez un montant ou un barreau. Tirez la main vers le bas pour monter,\nou levez-la pour descendre. Relâchez pour vous arrêter. Le bassin et les jambes natifs restent sur l'échelle.",
  ["Auto finish near ladder top"] = "Finir auto près du haut de l'échelle",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Après une traction vers le haut près du sommet, terminer la montée même si les mains lâchent.\nBougez le stick ou poussez une main tenue vers le haut pour annuler.",
  ["Ladder finish distance"] = "Distance de fin d'échelle",
  ["Turning (right stick)"] = "Rotation (stick droit)",
  ["Snap turn"] = "Rotation par crans",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Convertit l'axe X du stick droit en crans de rotation\nau lieu d'une rotation fluide. Aide contre le mal des transports.",
  ["Snap angle"] = "Angle des crans",
  ["STEREO"] = "STÉRÉO",
  ["PERFORMANCE"] = "PERFORMANCES",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Réglage du jeu",
  ["Off (higher FPS)"] = "Désactivé (FPS plus élevés)",
  ["On (lower latency)"] = "Activé (latence réduite)",
  ["On + Boost"] = "Activé + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Désactivé peut améliorer l'utilisation du GPU et les FPS, mais peut augmenter la latence d'entrée.",
  ["On"] = "Activé",
  ["Waiting for renderer"] = "En attente du moteur de rendu",
  ["Applied: %s"] = "Appliqué : %s",
  ["STEREO VIEW"] = "VUE STÉRÉO",
  ["Mono mode"] = "Mode mono",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Une seule image pour les deux yeux, rendue une fois depuis le centre de la tête :\npas de profondeur, le plus d'images par seconde. Stéréo moteur et seconde vue désactivées.",
  ["Restart the game to apply"] = "Redémarrez le jeu pour appliquer",
  ["Motion prediction (ms)"] = "Prédiction du mouvement (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Prédit la pose de la tête de ce nombre de ms selon sa\nvitesse, masquant la latence du rendu aux photons. 0 = désactivé.\nAugmentez jusqu'à ce que le mouvement soit réactif sans dépassement.",
  ["Stereo separation x"] = "Séparation stéréo x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Réglage personnel de l'IPD automatique. 1.0 = séparation naturelle\ncalibrée, mise à l'échelle sur l'IPD du runtime du casque. Ajustez\n0.8-1.2 selon vos goûts ; 3-5x exagère la profondeur et rend\nl'alternance des yeux visible sur l'écran plat pour les tests.",
  ["World scale"] = "Échelle du monde",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Met à l'échelle la séparation des yeux ET la translation de la tête ensemble.\nBaissez-la (ex. 0.8) pour que le monde paraisse\nPLUS GRAND / vous plus petit ; montez-la pour rétrécir le monde. Utile si V\net les PNJ semblent trop grands.",
  ["IPD scale"] = "Échelle de l'IPD",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Multiplicateur de séparation des yeux sur l'IPD du runtime. 1.0 = la base\nneutre (+-0.033 m sur un casque typique).\nAffecte la profondeur stéréo (diorama ou géant), PAS la taille monoculaire.",
  ["Reuse last clean frame"] = "Réutiliser la dernière image propre",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Sur les ticks périmés, renvoie le dernier œil capturé propre et laisse\nle compositeur le reprojeter, au lieu de déformer encore\nle contenu périmé. Peut réduire la fréquence d'envoi\nvers la fréquence de capture. Désactivé = toujours déformer l'œil périmé.",
  ["Asymmetric projection"] = "Projection asymétrique",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "ON : chaque œil rend exactement sa propre fenêtre de lentille décentrée\n(davantage du panneau utilisé, pixels carrés).\nOFF : le frustum symétrique dimensionné sur le demi-angle le plus large.",
  ["AVATAR"] = "AVATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "Raccourcis VR et actions du jeu par défaut. Les noms de boutons suivent la convention Touch / Xbox ; les actions du jeu utilisent vos assignations de manette.",
  ["LEFT STICK"] = "STICK GAUCHE",
  ["Move. Hold fully forward for 0.2 seconds to sprint."] = "Se déplacer. Maintenez à fond vers l'avant 0.2 seconde pour sprinter.",
  ["RIGHT STICK  Left / right"] = "STICK DROIT  Gauche / droite",
  ["Turn. Uses your snap-turn setting."] = "Tourner. Utilise votre réglage de rotation par crans.",
